package cn.iocoder.yudao.module.zsjos.service.handover;
import cn.iocoder.yudao.module.zsjos.dal.dataobject.handover.HandoverSheetDO; import cn.iocoder.yudao.module.zsjos.dal.mysql.handover.HandoverSheetMapper; import cn.iocoder.yudao.module.zsjos.framework.permission.ZsjosObjectPermissionProvider; import jakarta.annotation.Resource; import org.springframework.stereotype.Component; import java.util.Objects;
@Component public class HandoverObjectPermissionProvider implements ZsjosObjectPermissionProvider { @Resource private HandoverSheetMapper mapper; public String getBizType(){return "handover";} public boolean hasPermission(Long id,String action,Long userId){ HandoverSheetDO x=mapper.selectById(id); if(x==null)return false; if("arbitrate".equals(action))return Objects.equals(x.getArbitratorUserId(),userId); if("request-arbitration".equals(action))return Objects.equals(x.getFromUserId(),userId); return Objects.equals(x.getFromUserId(),userId)||Objects.equals(x.getToUserId(),userId); } }
